{"content":"def adventure():
    print("Welcome to the mini adventure!")
    print("You are in a dark forest. Choose a path:")
    print("1. Left")
    print("2. Right")
    choice = input("Enter 1 or 2: ")
    if choice == "1":
        print("You find a hidden cave! Great job.")
    elif choice == "2":
        print("You meet a friendly fox. It guides you home.")
    else:
        print("Unknown choice. The forest swallows you.")

if __name__ == "__main__":
    adventure()","path":"adventure.py"}

{"content":""""A tiny 2-choice adventure game."""


def main():
    print("=== Crossroads Adventure ===")
    print("You stand at a crossroads. A dark forest looms to the left,")
    print("a crumbling bridge crosses a rushing river to the right.")
    print()

    choice = input(
        "Type 'forest' to enter the forest, or 'bridge' to cross the river: "
    ).strip().lower()

    if choice == "forest":
        print("\nYou duck beneath mossy branches. Hours later, you discover")
        print("a ram","path":"adventure.py"}

